# -*- coding: utf-8 -*-
"""扫描件（纯图片 PDF）翻译管线 —— Mac 与 Windows 共用。

普通 PDF 走 pdf2zh 原有管线即可；扫描件整页是图片，套用普通流程会出两类问题：
版面模型把部分正文误判成图/公式而漏翻、且原扫描图一直垫在底下导致英文透出来，
中英糊叠。这里自成一条管线：

    OCR 识别 → 版面分区(表格/插图保原图，文本才翻) → 分栏 → 缩进分段
    → 整段翻译 → 思源宋体白底渲染（旋转内容按原方向竖排还原）

产出 mono（纯译文白底页）与 dual（原扫描页 / 译文页 交替，供并排对照）。
"""
import os
import fitz


class ScannedPdfTranslator:
    """扫描件翻译管线。调用方（Mac 的 TranslateWorker / Windows 的 TranslateWorker）
    只需传入文件、输出目录、页码范围、目标语言、翻译器实例、版面模型和几个回调。

    translator: 需实现 .translate(text) -> str
    layout_model: pdf2zh 的 doclayout 模型（可为 None，退化成不分区）
    status_cb(str) / progress_cb(cur, total) / is_cancelled() -> bool 均可选
    """

    def __init__(self, file_path, output_dir, pages, lang_out, translator,
                 layout_model=None, status_cb=None, progress_cb=None,
                 is_cancelled=None, asset_dir=None):
        self.file_path = file_path
        self.output_dir = output_dir
        self.pages = pages                 # 0-indexed 页码列表；None=全部
        self.lang_out = lang_out
        self.translator = translator
        self.layout_model = layout_model
        self._status_cb = status_cb
        self._progress_cb = progress_cb
        self._cancel_cb = is_cancelled
        self.asset_dir = asset_dir         # 放思源宋体的目录

    def _status(self, msg):
        if self._status_cb:
            try: self._status_cb(msg)
            except Exception: pass

    def _progress(self, cur, total):
        if self._progress_cb:
            try: self._progress_cb(cur, total)
            except Exception: pass

    def is_cancelled(self):
        try:
            return bool(self._cancel_cb()) if self._cancel_cb else False
        except Exception:
            return False

    def translate(self):
        """入口：返回 (mono_path, dual_path)。"""
        return self._ocr_standalone_translate(layout_model=self.layout_model)

    @staticmethod
    def _ocr_classify_flows(lines, page_width):
        """v2.3.22: 按“栏间白槽”把行分到 整宽 / 左栏 / 右栏 三个文本流。
        之前只按行中心 cx 跟页面中线比，遇到"单栏摘要 + 双栏正文 + 脚注"混排的
        标题页会把栏分错、把跨栏整宽行(标题/摘要)硬塞进某一栏。改成:先统计每个
        横向位置被多少行覆盖，在页面中段找覆盖最低的竖直白槽——真正的栏间缝；有
        清晰白槽才算双栏。跨白槽的行(标题/摘要/脚注分隔)归"整宽流"，其余按在白槽
        哪侧归左/右栏。返回 {"full":[...], "L":[...], "R":[...]}（无双栏时全在 full）。"""
        flows = {"full": [], "L": [], "R": []}
        if not lines:
            return flows
        BIN = 4
        nb = int(page_width // BIN) + 1
        cov = [0] * nb
        for l in lines:
            for b in range(int(l["x0"] // BIN), int(l["x1"] // BIN) + 1):
                if 0 <= b < nb:
                    cov[b] += 1
        lo, hi = int(0.35 * page_width // BIN), int(0.65 * page_width // BIN)
        if hi <= lo:
            flows["full"] = list(lines); return flows
        gut_b = min(range(lo, hi), key=lambda b: cov[b])
        gutter = gut_b * BIN
        mid_cov = sorted(cov[int(0.1 * nb):int(0.9 * nb)] or [0])
        med = mid_cov[len(mid_cov) // 2] if mid_cov else 0
        two_col = med > 0 and cov[gut_b] < med * 0.35
        if not two_col:
            flows["full"] = list(lines); return flows
        for l in lines:
            if l["x0"] < gutter - 10 and l["x1"] > gutter + 10:
                flows["full"].append(l)
            elif l["cx"] < gutter:
                flows["L"].append(l)
            else:
                flows["R"].append(l)
        return flows

    @staticmethod
    def _ocr_group_paragraphs(flow_lines):
        """流内按缩进 + 竖直间距分段。学术论文段落分界主要靠"首行缩进"(首行 x0
        比该栏左边距大一点)，其次靠段间空隙。之前只看 gap/相邻行 x0 跳变，抓不到
        小缩进、又会被两端对齐里最后一行变短误伤。改成:以该栏最常见 x0 为左边距，
        某行 x0 明显大于左边距(缩进)或与上一行间距明显变大 → 新段起。"""
        fl = sorted(flow_lines, key=lambda l: l["y0"])
        if not fl:
            return []
        heights = sorted(l["y1"] - l["y0"] for l in fl)
        med_h = heights[len(heights) // 2] or 10
        from collections import Counter
        margin = Counter(round(l["x0"] / 3) * 3 for l in fl).most_common(1)[0][0]
        paras, cur = [], [fl[0]]
        for prev, ln in zip(fl, fl[1:]):
            indented = ln["x0"] > margin + med_h * 0.25
            big_gap = (ln["y0"] - prev["y1"]) > med_h * 0.7
            if indented or big_gap:
                paras.append(cur); cur = [ln]
            else:
                cur.append(ln)
        paras.append(cur)
        return paras

    # 区域类型：保留原样(不翻、直接贴原扫描图)的类别 —— 表格和插图/公式重排会毁掉
    # 结构(表格被当成流式段落切碎、数字表头全错位)，保原图至少排版完整可读。
    _OCR_KEEP_CLASSES = {"table", "figure", "isolate_formula"}
    # 需要翻译的文本类区域
    _OCR_TEXT_CLASSES = {"title", "plain text", "abandon", "figure_caption",
                         "table_caption", "table_footnote", "formula_caption"}

    @staticmethod
    def _ocr_layout_regions(layout_model, pix, pw, ph):
        """v2.3.24: 借用正常管线的版面模型(doclayout)给扫描页分区，返回
        [{'cls':类别, 'rect':PDF坐标框, 'conf':置信度}]。之前 OCR 管线完全没有
        "区域类型"概念，把整页(含表格/插图/旋转内容)一律当流式正文重排，表格被
        切成段落、数字表头全错位。有了分区就能按类型分流:表格/插图保原图，文本
        才翻译；而且模型给出的 plain text 框本身就是按栏切好的，比手写白槽/缩进
        启发式可靠。"""
        try:
            import numpy as np, cv2
            img = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)
            if pix.n == 4:
                img = cv2.cvtColor(img, cv2.COLOR_RGBA2RGB)
            elif pix.n == 1:
                img = cv2.cvtColor(img, cv2.COLOR_GRAY2RGB)
            res = layout_model.predict(img, imgsz=1024)[0]
            sx, sy = pw / pix.width, ph / pix.height
            out = []
            for b in res.boxes:
                cls = res.names[int(b.cls)]
                x0, y0, x1, y1 = [float(v) for v in b.xyxy]
                out.append({"cls": cls, "conf": float(b.conf),
                            "rect": fitz.Rect(x0 * sx, y0 * sy, x1 * sx, y1 * sy)})
            return out
        except Exception:
            return []

    @staticmethod
    def _ocr_merge_keep_regions(regions):
        """把要保原图的区域(表格/插图/公式)按重叠合并，避免同一张表被拆成多块
        分别贴导致接缝。低置信度的表格框也保留——宁可多保一块原图，也不要让
        表格被当正文重排搅烂。"""
        keeps = [r["rect"] for r in regions if r["cls"] in ScannedPdfTranslator._OCR_KEEP_CLASSES]
        merged = []
        for r in sorted(keeps, key=lambda r: (r.y0, r.x0)):
            hit = None
            for m in merged:
                if m.intersects(r):
                    hit = m; break
            if hit is not None:
                hit |= r  # 并集
            else:
                merged.append(+r)
        return merged

    def _ocr_standalone_translate(self, layout_model=None):
        """扫描件独立翻译管线。产出 (mono_path, dual_path)。
        mono = 纯译文白底页；dual = [原扫描页, 译文页, ...] 交替（供并排版/对照）。
        v2.3.24: 接入正常管线的版面模型做区域分流——表格/插图保原图，文本才翻译。"""
        from rapidocr_onnxruntime import RapidOCR
        translator = self.translator
        ocr = RapidOCR()
        src = fitz.open(self.file_path)
        if self.pages:
            page_indices = [p for p in self.pages if 0 <= p < src.page_count]
        else:
            page_indices = list(range(src.page_count))
        total = len(page_indices)
        font_bytes = self._ocr_font_bytes()  # 思源宋体/GoNoto，和普通翻译同款好看字体

        mono = fitz.open()
        dual = fitz.open()
        try:
            for i, pno in enumerate(page_indices):
                if self.is_cancelled():
                    break
                tdoc = self._ocr_translate_one_page(src, pno, ocr, translator,
                                                    layout_model, font_bytes)
                mono.insert_pdf(tdoc)                             # 译文页
                dual.insert_pdf(src, from_page=pno, to_page=pno)  # 原扫描页
                dual.insert_pdf(tdoc)                             # 译文页
                tdoc.close()
                self._progress(i + 1, total)
                self._status(f"扫描件翻译… {i+1}/{total}")

            base = os.path.splitext(os.path.basename(self.file_path))[0]
            os.makedirs(self.output_dir, exist_ok=True)
            mono_path = os.path.join(self.output_dir, f"{base}-mono.pdf")
            dual_path = os.path.join(self.output_dir, f"{base}-dual.pdf")
            # garbage=4:insert_htmlbox 每次会独立内嵌一份中文字体子集，不回收的话几十段
            # 能把文件撑到几十 MB；garbage=4 合并重复字体子集，实测 34MB→1.8MB。
            mono.save(mono_path, garbage=4, deflate=True)
            dual.save(dual_path, garbage=4, deflate=True)
            return mono_path, dual_path
        finally:
            src.close(); mono.close(); dual.close()

    @staticmethod
    def _ocr_lines_from_pix(ocr, pix, pw, ph):
        """对一张页面位图跑 OCR，返回 PDF 坐标系下的文字行列表。"""
        result, _ = ocr(pix.tobytes("png"))
        sx, sy = pw / pix.width, ph / pix.height
        lines = []
        for box, text, conf in (result or []):
            if conf < 0.5 or not text.strip():
                continue
            x0 = min(p[0] for p in box) * sx
            y0 = min(p[1] for p in box) * sy
            x1 = max(p[0] for p in box) * sx
            y1 = max(p[1] for p in box) * sy
            lines.append({"x0": x0, "y0": y0, "x1": x1, "y1": y1,
                          "cx": (x0 + x1) / 2, "text": text})
        return lines

    def _ocr_translate_one_page(self, src, pno, ocr, translator, layout_model, font_bytes):
        """翻译扫描件的一页，返回只含该译文页的 1 页文档（几何和原页一致）。
        v2.3.24: 内含"整页旋转"处理——论文里横向排版的整页大表(把页面转90°才能读)
        直接按横排逻辑处理必然崩(分栏/分段全错)。这里先按 OCR 文字框的长宽比判断
        整页是不是旋转内容，是的话用 show_pdf_page 造一张"转正"的临时页，在转正
        空间里跑完整流程(分区/分段/翻译/排版)，最后把渲染结果整页转回原朝向——
        既不用手推坐标变换，也复用了全部现有逻辑。"""
        page = src[pno]
        pw, ph = page.rect.width, page.rect.height
        pix = page.get_pixmap(dpi=300)
        lines = self._ocr_lines_from_pix(ocr, pix, pw, ph)

        # 注：不做"整页转正"。实测版面模型在扫描页的原始朝向下识别更准(第12页那种
        # 整页横排大表，原朝向能识别出 table 并整块保原图；先把页面转正反而识别不到)。
        # 旋转的文字按"区域"单独处理：OCR 本来就能读出旋转文字的内容，只是框是竖条，
        # 分段时把坐标转置复用同一套逻辑，渲染时用 insert_htmlbox(rotate=) 竖排回去。
        return self._ocr_build_page(src, pno, pix, lines, pw, ph,
                                    translator, layout_model, font_bytes)

    def _ocr_build_page(self, src, pno, pix, lines, pw, ph, translator,
                        layout_model, font_bytes):
        """在"已转正"的坐标系里，把一页拆区域→翻译→排版，返回 1 页文档。"""
        # 版面分区：表格/插图/公式整块保留原扫描图，其余文字才翻译
        keep_rects = []
        if layout_model is not None:
            regions = self._ocr_layout_regions(layout_model, pix, pw, ph)
            keep_rects = self._ocr_merge_keep_regions(regions)
            if keep_rects:
                def _in_keep(l):
                    c = fitz.Point((l["x0"] + l["x1"]) / 2, (l["y0"] + l["y1"]) / 2)
                    return any(c in k for k in keep_rects)
                lines = [l for l in lines if not _in_keep(l)]

        # 横排行和"竖条行"(旋转文字)分开处理。旋转文字 OCR 内容是对的、只是框是
        # 竖条，直接套横排的分栏/分段逻辑会全错；把坐标转置后复用同一套逻辑分段，
        # 再把段落框转置回来、渲染时按 rotate 竖排回去。
        horiz = [l for l in lines if (l["y1"] - l["y0"]) <= (l["x1"] - l["x0"]) * 1.5]
        rot = [l for l in lines if (l["y1"] - l["y0"]) > (l["x1"] - l["x0"]) * 1.5]

        paras = []
        flows = self._ocr_classify_flows(horiz, pw)
        for flow_key in ("full", "L", "R"):
            for grp in self._ocr_group_paragraphs(flows[flow_key]):
                txt = " ".join(g["text"] for g in grp)
                bx0 = min(g["x0"] for g in grp); by0 = min(g["y0"] for g in grp)
                bx1 = max(g["x1"] for g in grp); by1 = max(g["y1"] for g in grp)
                hs = sorted(g["y1"] - g["y0"] for g in grp)
                paras.append({"rect": fitz.Rect(bx0, by0, bx1, by1), "text": txt,
                              "line_h": hs[len(hs) // 2] or 10, "flow": flow_key,
                              "rotate": 0})
        if rot:
            # 转置:(x,y)→(y,x)，让竖排文字在转置空间里表现为横排，复用分栏/分段
            tr = [{"x0": l["y0"], "y0": l["x0"], "x1": l["y1"], "y1": l["x1"],
                   "cx": (l["y0"] + l["y1"]) / 2, "text": l["text"]} for l in rot]
            tflows = self._ocr_classify_flows(tr, ph)
            for flow_key in ("full", "L", "R"):
                for grp in self._ocr_group_paragraphs(tflows[flow_key]):
                    txt = " ".join(g["text"] for g in grp)
                    ty0 = min(g["x0"] for g in grp); tx0 = min(g["y0"] for g in grp)
                    ty1 = max(g["x1"] for g in grp); tx1 = max(g["y1"] for g in grp)
                    hs = sorted(g["y1"] - g["y0"] for g in grp)   # 转置空间的"行高"= 原来的框宽
                    paras.append({"rect": fitz.Rect(tx0, ty0, tx1, ty1), "text": txt,
                                  "line_h": hs[len(hs) // 2] or 10,
                                  "flow": "rot_" + flow_key, "rotate": 90})

        for p in paras:
            try:
                zh = translator.translate(p["text"])
            except Exception:
                zh = None
            p["zh"] = (zh or p["text"]).strip()

        out = fitz.open()
        op = out.new_page(width=pw, height=ph)
        for kr in keep_rects:                       # 先贴保留区原图(表格/插图)
            try:
                op.show_pdf_page(kr, src, pno, clip=kr)
            except Exception:
                pass
        self._ocr_render_page(op, paras, ph, font_bytes)
        return out


    def _ocr_font_bytes(self):
        """取译文渲染用的字体(和普通 pdf2zh 翻译同款好看字体，而非 fitz 默认的
        瘦扁 sans-serif)。zh 用打包内的思源宋体(离线也在)；其它语言用 pdf2zh 的
        download_remote_fonts(会缓存)。都拿不到返回 None，渲染时退回 sans-serif。"""
        lang = (self.lang_out or "zh").lower()
        # 依次找：调用方指定的 assets 目录 → 冻结包目录 → 本模块上两级(源码布局)
        cands = []
        try:
            import sys
            if self.asset_dir:
                cands.append(self.asset_dir)
            mei = getattr(sys, "_MEIPASS", None)
            if mei:
                cands.append(os.path.join(mei, "assets"))
            here = os.path.dirname(os.path.abspath(__file__))          # .../pdf2zh
            cands.append(os.path.join(here, "..", "..", "..", "assets"))  # 仓库根/assets
            cands.append(os.path.join(here, "assets"))
        except Exception:
            pass
        if lang.startswith("zh"):
            for d in cands:
                try:
                    p = os.path.join(d, "SourceHanSerifCN-Regular.ttf")
                    if os.path.exists(p):
                        with open(p, "rb") as f:
                            return f.read()
                except Exception:
                    continue
        try:
            from pdf2zh.high_level import download_remote_fonts
            p = download_remote_fonts(lang)
            if p and os.path.exists(p):
                with open(p, "rb") as f:
                    return f.read()
        except Exception:
            pass
        return None

    @staticmethod
    def _ocr_render_page(page, paras, page_h, font_bytes):
        """整页渲染译文（v2.3.22b）：统一字号 + 统一行距 + 思源宋体 + 锚定原位置，
        每段框裁剪到"同栏下一段顶部"防止长译文压到下一段。
        之前(v2.3.22)按每段"填满原框"反推行距，导致同样大小的段落译出来字号、行距
        各不相同(用户反馈"字体和行距不同")；且用的是 fitz 默认 sans-serif(不好看)。
        这版:整页正文用同一个字号(取各段行高中位数)、同一个行距(1.35)，字体换成和
        普通翻译一致的思源宋体；锚定原位置保留版式，靠裁剪到下一段避免重叠。"""
        vis = [p for p in paras if (p.get("zh") or "").strip()]
        if not vis:
            return
        body_h = sorted(p["line_h"] for p in vis if p["line_h"] < 16)
        uni_h = body_h[len(body_h) // 2] if body_h else 10
        fs = max(uni_h * 0.95, 7.5)
        arc = None
        fam = "sans-serif"
        face = ""
        if font_bytes:
            try:
                arc = fitz.Archive()
                arc.add(font_bytes, "han.ttf")
                fam = "han"
                face = "@font-face{font-family:han;src:url(han.ttf);}"
            except Exception:
                arc = None; fam = "sans-serif"; face = ""
        flow_keys = sorted({p.get("flow", "full") for p in vis})
        for flow_key in flow_keys:
            fp = [p for p in vis if p.get("flow") == flow_key]
            rotated = bool(fp) and fp[0].get("rotate", 0)
            # 竖排流按 x 排序(视觉上从左到右就是阅读顺序)，横排流按 y
            fp.sort(key=lambda p: (p["rect"].x0 if rotated else p["rect"].y0))
            for i, p in enumerate(fp):
                r = p["rect"]
                pfs = fs * 1.4 if p["line_h"] >= 16 else fs   # 标题类稍大
                css = (f"{face}* {{font-family:{fam};font-size:{pfs:.1f}px;"
                       f"line-height:1.35;color:black;}}")
                esc = p["zh"].replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                if rotated:
                    # 竖排:裁剪到同流下一段的左边界，避免压到相邻竖排块
                    next_x = fp[i + 1]["rect"].x0 - 2 if i + 1 < len(fp) else page.rect.x1
                    right = min(max(next_x, r.x0 + pfs * 1.2), page.rect.x1)
                    box = fitz.Rect(r.x0, r.y0, right, r.y1)
                else:
                    next_top = fp[i + 1]["rect"].y0 - 2 if i + 1 < len(fp) else page_h
                    bottom = min(max(next_top, r.y0 + pfs * 1.2), page_h)
                    box = fitz.Rect(r.x0, r.y0, r.x1, bottom)
                rot = int(p.get("rotate", 0)) or 0
                try:
                    if arc is not None:
                        page.insert_htmlbox(box, esc, css=css, archive=arc,
                                            rotate=rot, scale_low=0)
                    else:
                        page.insert_htmlbox(box, esc, css=css, rotate=rot, scale_low=0)
                except Exception:
                    pass